import React, { useState, useEffect } from "react";
import axios from "axios";

function KitchenDashboard() {
  const [orders, setOrders] = useState([]);
  const [chefId, setChefId] = useState("");

  // Load orders on mount
  useEffect(() => {
    refreshOrders();
  }, []);

  // Refresh orders list
  const refreshOrders = () => {
    axios.get("http://localhost:5000/api/orders")
      .then(res => setOrders(res.data))
      .catch(err => console.error("Error fetching orders:", err));
  };

  // Assign chef to an order
  const assignChef = (orderId) => {
    const chefIdNumber = parseInt(chefId, 10);
    if (!chefIdNumber) {
      alert("Please enter a valid Chef ID first");
      return;
    }

    axios.put(`http://localhost:5000/api/orders/${orderId}/assign-chef`, { chefId: chefIdNumber })
      .then(() => {
        alert(`Chef ${chefIdNumber} assigned to order ${orderId}`);
        refreshOrders();
      })
      .catch(err => {
        const message = err.response?.data?.error || err.message;
        alert("Error assigning chef: " + message);
      });
  };

  // Update order status
  const updateStatus = (orderId, status) => {
    axios.put(`http://localhost:5000/api/orders/${orderId}/status`, { status })
      .then(() => {
        alert(`Order ${orderId} updated to ${status}`);
        refreshOrders();
      })
      .catch(err => alert("Error updating status: " + err.message));
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Kitchen Dashboard</h2>

      <div style={{ marginBottom: "20px" }}>
        <label>
          Enter Chef ID:{" "}
          <input
            type="text"
            value={chefId}
            onChange={e => setChefId(e.target.value)}
          />
        </label>
      </div>

      {orders.length === 0 ? (
        <p>No orders yet.</p>
      ) : (
        <ul>
          {orders.map(order => (
            <li key={order.id} style={{ marginBottom: "15px" }}>
              <strong>Order {order.id}</strong> — 
              Table {order.table_number || "N/A"} — 
              Status: {order.status} — 
              Chef: {order.chef_id || "Unassigned"}
              <div style={{ marginTop: "5px" }}>
                <button onClick={() => assignChef(order.id)}>
                  {order.chef_id ? "Reassign Chef" : "Assign Chef"}
                </button>
                {order.status === "Received" && (
                  <button onClick={() => updateStatus(order.id, "Preparing")}>
                    Start Preparing
                  </button>
                )}
                {order.status === "Preparing" && (
                  <button onClick={() => updateStatus(order.id, "Ready")}>
                    Mark Ready
                  </button>
                )}
                {order.status === "Ready" && (
                  <button disabled>Waiting for Payment</button>
                )}
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default KitchenDashboard;
